#ifndef STDLIB_LAPACK_BASE_DLASYF_VALIDATION_H
#define STDLIB_LAPACK_BASE_DLASYF_VALIDATION_H

#include "stdlib/lapack/base/shared.h"
#include "stdlib/lapack/base/xerbla.h"
#include <limits.h>
#include <stddef.h>
#include <stdint.h>

typedef char dlasyf_lapack_integer_check[ ( sizeof( LAPACK_INT ) <= sizeof( intmax_t ) && (LAPACK_INT)-1 < 0 ) ? 1 : -1 ];
typedef char dlasyf_blas_integer_check[ ( sizeof( CBLAS_INT ) <= sizeof( intmax_t ) && (CBLAS_INT)-1 < 0 ) ? 1 : -1 ];

typedef struct dlasyf_envelope {
	uintptr_t first;
	uintptr_t last;
} dlasyf_envelope;

/**
* Returns the largest configured LAPACK integer.
*/
static intmax_t dlasyf_lapack_max( void ) {
	return (intmax_t)( UINTMAX_MAX >> ( (sizeof( uintmax_t )-sizeof( LAPACK_INT ))*CHAR_BIT + 1 ) );
}

/**
* Returns the largest configured BLAS integer independently of LAPACK_INT.
*/
static uintmax_t dlasyf_blas_max( void ) {
	return UINTMAX_MAX >> ( (sizeof( uintmax_t )-sizeof( CBLAS_INT ))*CHAR_BIT + 1 );
}

/**
* Computes a magnitude without negating a minimum signed integer.
*/
static uintmax_t dlasyf_magnitude( const intmax_t value ) {
	return value < 0 ? (uintmax_t)( -(value+1) )+1 : (uintmax_t)value;
}

/**
* Computes an exact, checked configured LAPACK integer product.
*/
static int dlasyf_product( const uintmax_t count, const intmax_t stride, intmax_t *result ) {
	const intmax_t limit = dlasyf_lapack_max();
	uintmax_t magnitude;
	uintmax_t bound;

	if ( count == 0 || stride == 0 ) {
		*result = 0;
		return 1;
	}
	magnitude = dlasyf_magnitude( stride );
	bound = (uintmax_t)limit + ( stride < 0 ? 1 : 0 );
	if ( count > bound/magnitude ) {
		return 0;
	}
	magnitude *= count;
	if ( stride < 0 ) {
		*result = magnitude == (uintmax_t)limit+1 ? -limit-1 : -(intmax_t)magnitude;
	} else {
		*result = (intmax_t)magnitude;
	}
	return 1;
}

/**
* Computes an exact, checked configured LAPACK integer sum.
*/
static int dlasyf_sum( const intmax_t x, const intmax_t y, intmax_t *result ) {
	const intmax_t limit = dlasyf_lapack_max();
	const intmax_t minimum = -limit-1;

	if ( ( y > 0 && x > limit-y ) || ( y < 0 && x < minimum-y ) ) {
		return 0;
	}
	*result = x+y;
	return 1;
}

/**
* Returns the greatest common divisor of two nonzero magnitudes.
*/
static uintmax_t dlasyf_gcd( uintmax_t x, uintmax_t y ) {
	uintmax_t remainder;

	while ( y != 0 ) {
		remainder = x%y;
		x = y;
		y = remainder;
	}
	return x;
}

/**
* Checks an inclusive physical byte envelope without forming derived pointers.
*/
static int dlasyf_envelope_valid( const void *data, const intmax_t first, const intmax_t last, const size_t size, dlasyf_envelope *envelope ) {
	const uintptr_t address = (uintptr_t)data;
	uintmax_t last_byte;
	uintmax_t first_byte;

	if ( first < 0 || last < first || (uintmax_t)last > ( (uintmax_t)PTRDIFF_MAX-(size-1) )/size ) {
		return 0;
	}
	first_byte = (uintmax_t)first*size;
	last_byte = (uintmax_t)last*size+(size-1);
	if ( last_byte > UINTPTR_MAX || address > UINTPTR_MAX-(uintptr_t)last_byte ) {
		return 0;
	}
	envelope->first = address+(uintptr_t)first_byte;
	envelope->last = address+(uintptr_t)last_byte;
	return 1;
}

/**
* Checks conservative physical byte-envelope overlap.
*/
static int dlasyf_overlap( const dlasyf_envelope *x, const dlasyf_envelope *y ) {
	return x->first <= y->last && y->first <= x->last;
}

/**
* Validates matrix geometry and reports the offending component (1,2,3).
*/
static int dlasyf_matrix_valid( const void *data, const intmax_t rows, const intmax_t columns, const intmax_t stride1, const intmax_t stride2, const intmax_t offset, dlasyf_envelope *envelope ) {
	uintmax_t magnitude1;
	uintmax_t magnitude2;
	uintmax_t divisor;
	intmax_t delta1;
	intmax_t delta2;
	intmax_t corner1;
	intmax_t corner2;
	intmax_t corner3;
	intmax_t first;
	intmax_t last;

	if ( ( rows > 1 && stride1 == 0 ) || !dlasyf_product( (uintmax_t)(rows-1), stride1, &delta1 ) ) {
		return 1;
	}
	if ( ( columns > 1 && stride2 == 0 ) || !dlasyf_product( (uintmax_t)(columns-1), stride2, &delta2 ) ) {
		return 2;
	}
	if ( rows > 1 && columns > 1 ) {
		magnitude1 = dlasyf_magnitude( stride1 );
		magnitude2 = dlasyf_magnitude( stride2 );
		divisor = dlasyf_gcd( magnitude1, magnitude2 );
		if ( magnitude2/divisor < (uintmax_t)rows && magnitude1/divisor < (uintmax_t)columns ) {
			return 2;
		}
	}
	if ( !dlasyf_sum( offset, delta1, &corner1 ) || !dlasyf_sum( offset, delta2, &corner2 ) || !dlasyf_sum( corner1, delta2, &corner3 ) ) {
		return 3;
	}
	first = offset;
	last = offset;
	if ( corner1 < first ) first = corner1;
	if ( corner2 < first ) first = corner2;
	if ( corner3 < first ) first = corner3;
	if ( corner1 > last ) last = corner1;
	if ( corner2 > last ) last = corner2;
	if ( corner3 > last ) last = corner3;
	return dlasyf_envelope_valid( data, first, last, sizeof( double ), envelope ) ? 0 : 3;
}

/**
* Guards all potential copy/scale/swap casts and C/Fortran poststeps.
*
* Calls are rebased to offset zero. Copy chunks never exceed seven elements;
* this bound also covers Fortran one-based indices, DSCAL's N*abs(stride)
* loop endpoint, and final unrolled loop-control increments. Singleton calls
* normalize the otherwise unused stride to one.
*/
static int dlasyf_blas_valid( const intmax_t count, const intmax_t stride ) {
	const uintmax_t limit = dlasyf_blas_max();
	const uintmax_t length = (uintmax_t)count;
	const uintmax_t magnitude = dlasyf_magnitude( stride );

	if ( count <= 1 ) {
		return 1;
	}
	if ( length > limit || limit-length < 8 || magnitude == 0 || magnitude > limit ) {
		return 0;
	}
	return length <= (limit-1)/magnitude;
}

/**
* Validates all active views, disjointness and potential helper arithmetic.
*/
static LAPACK_INT dlasyf_validate( const LAPACK_UPLO uplo, const LAPACK_INT N, const LAPACK_INT NB, const LAPACK_INT *KB, const LAPACK_INT offsetKB, const double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA, const LAPACK_INT *IPIV, const LAPACK_INT strideIPIV, const LAPACK_INT offsetIPIV, const double *W, const LAPACK_INT strideW1, const LAPACK_INT strideW2, const LAPACK_INT offsetW ) {
	dlasyf_envelope kb;
	dlasyf_envelope a;
	dlasyf_envelope p;
	dlasyf_envelope w;
	intmax_t delta;
	intmax_t endpoint;
	intmax_t first;
	intmax_t last;
	int error;

	if ( uplo != LAPACK_UPPER_TRIANGLE && uplo != LAPACK_LOWER_TRIANGLE ) return -1;
	if ( N < 0 ) return -2;
	if ( NB < 2 ) return -3;
	if ( KB == NULL ) return -4;
	if ( !dlasyf_envelope_valid( KB, offsetKB, offsetKB, sizeof( LAPACK_INT ), &kb ) ) return -5;
	if ( N == 0 ) return 0;
	if ( (intmax_t)N > dlasyf_lapack_max()-2 ) return -2;
	if ( A == NULL ) return -6;
	error = dlasyf_matrix_valid( A, N, N, strideA1, strideA2, offsetA, &a );
	if ( error != 0 ) return (LAPACK_INT)(-6-error);
	if ( dlasyf_overlap( &kb, &a ) ) return -6;
	if ( IPIV == NULL ) return -10;
	if ( ( N > 1 && strideIPIV == 0 ) || !dlasyf_product( (uintmax_t)(N-1), strideIPIV, &delta ) ) return -11;
	if ( !dlasyf_sum( offsetIPIV, delta, &endpoint ) ) return -12;
	first = offsetIPIV < endpoint ? offsetIPIV : endpoint;
	last = offsetIPIV > endpoint ? offsetIPIV : endpoint;
	if ( !dlasyf_envelope_valid( IPIV, first, last, sizeof( LAPACK_INT ), &p ) ) return -12;
	if ( dlasyf_overlap( &kb, &p ) || dlasyf_overlap( &a, &p ) ) return -10;
	if ( W == NULL ) return -13;
	error = dlasyf_matrix_valid( W, N, NB, strideW1, strideW2, offsetW, &w );
	if ( error != 0 ) return (LAPACK_INT)(-13-error);
	if ( dlasyf_overlap( &kb, &w ) || dlasyf_overlap( &a, &w ) || dlasyf_overlap( &p, &w ) ) return -13;
	if ( !dlasyf_blas_valid( N, strideA1 ) ) return -7;
	if ( !dlasyf_blas_valid( N, strideA2 ) ) return -8;
	if ( !dlasyf_blas_valid( N, strideW1 ) ) return -14;
	if ( !dlasyf_blas_valid( N, strideW2 ) ) return -15;
	return 0;
}

/**
* Prints an adopted LAPACK diagnostic and returns this routine's error status.
*/
static LAPACK_INT dlasyf_error( const char *name, const LAPACK_INT info ) {
	API_SUFFIX(lapack_xerbla)( name, info );
	return info;
}

#endif // !STDLIB_LAPACK_BASE_DLASYF_VALIDATION_H
